import { OdooAuthResponse, OdooRpcResponse, OdooSession } from '@/types/odoo';

// Configuration constants
const ODOO_URL = process.env.NEXT_PUBLIC_ODOO_URL || 'https://demo18.infinia.id';
const ODOO_DB = process.env.NEXT_PUBLIC_ODOO_DB || 'test16';

interface JsonRpcParams {
    service?: string;
    method?: string;
    args?: unknown[];
    model?: string;
    kwargs?: Record<string, unknown>;
    [key: string]: unknown; // Allow other properties like db, login for authenticate
}

/**
 * Odoo JSON-RPC Client
 * Handles authentication and API calls to Odoo backend
 */
export class OdooClient {
    private baseUrl: string;
    private db: string;
    private sessionId: string | null = null;
    private uid: number = 0;

    constructor(baseUrl: string = ODOO_URL, db: string = ODOO_DB) {
        this.baseUrl = baseUrl;
        this.db = db;
    }

    /**
     * Make a JSON-RPC call to Odoo
     */
    private async jsonRpc<T>(
        endpoint: string,
        params: JsonRpcParams
    ): Promise<OdooRpcResponse<T>> {
        const headers: Record<string, string> = {
            'Content-Type': 'application/json',
        };

        if (this.sessionId) {
            headers['Cookie'] = `session_id=${this.sessionId}`;
        }

        const response = await fetch(`${this.baseUrl}${endpoint}`, {
            method: 'POST',
            headers,
            credentials: 'include',
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params,
                id: Math.floor(Math.random() * 1000000),
            }),
        });

        // Extract session cookie if present
        const setCookie = response.headers.get('set-cookie');
        if (setCookie) {
            const sessionMatch = setCookie.match(/session_id=([^;]+)/);
            if (sessionMatch) {
                this.sessionId = sessionMatch[1];
            }
        }

        return response.json();
    }

    /**
     * Authenticate with Odoo
     */
    async authenticate(
        username: string,
        password: string
    ): Promise<{ success: boolean; session?: OdooSession; error?: string }> {
        try {
            const response = await fetch(`${this.baseUrl}/web/session/authenticate`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                credentials: 'include',
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        db: this.db,
                        login: username,
                        password: password,
                    },
                    id: Math.floor(Math.random() * 1000000),
                }),
            });

            const data: OdooAuthResponse = await response.json();

            if (data.error) {
                return {
                    success: false,
                    error: data.error.data?.message || data.error.message || 'Authentication failed',
                };
            }

            if (data.result && data.result.uid) {
                // Store session ID
                const setCookie = response.headers.get('set-cookie');
                if (setCookie) {
                    const sessionMatch = setCookie.match(/session_id=([^;]+)/);
                    if (sessionMatch) {
                        this.sessionId = sessionMatch[1];
                    }
                }

                if (typeof data.result.uid === 'number') {
                    this.uid = data.result.uid;
                }

                return {
                    success: true,
                    session: {
                        ...data.result,
                        session_id: this.sessionId || '',
                    },
                };
            }

            return {
                success: false,
                error: 'Invalid credentials',
            };
        } catch (error) {
            return {
                success: false,
                error: error instanceof Error ? error.message : 'Network error',
            };
        }
    }

    /**
     * Check if session is still valid
     */
    async checkSession(): Promise<{ valid: boolean; session?: OdooSession }> {
        try {
            const response = await this.jsonRpc<OdooSession>('/web/session/get_session_info', {
                service: 'web',
                method: 'get_session_info',
                args: [],
            });

            if (response.result && response.result.uid) {
                if (typeof response.result.uid === 'number') {
                    this.uid = response.result.uid;
                }
                return { valid: true, session: response.result };
            }

            return { valid: false };
        } catch {
            return { valid: false };
        }
    }

    /**
     * Call an Odoo model method
     */
    async call<T>(
        model: string,
        method: string,
        args: unknown[] = [],
        kwargs: Record<string, unknown> = {}
    ): Promise<OdooRpcResponse<T>> {
        // We ensure getUserId is called (which checks session), but we don't pass uid explicitly in args for call_kw
        // as the session context handles it on the server side (usually).
        await this.getUserId();

        return this.jsonRpc<T>('/web/dataset/call_kw', {
            model: model,
            method: method,
            args: args,
            kwargs: kwargs,
        });
    }

    /**
     * Search and read records
     */
    async searchRead<T>(
        model: string,
        domain: unknown[] = [],
        fields: string[] = [],
        options: { limit?: number; offset?: number; order?: string } = {}
    ): Promise<T[]> {
        const response = await this.call<T[]>(model, 'search_read', [domain], {
            fields,
            ...options
        });

        // The web controller usually unwraps the result directly if successful,
        // but let's stick to our standardized response wrapper interface.
        // Actually, for web/dataset/call_kw, the structure is usually inside 'result'.
        // If our jsonRpc() generic handles the outer envelope {jsonrpc:.., result:..},
        // then response.result holds the actual return value of the python method.
        // for search_read, it returns a list of dicts.
        return response.result || [];
    }

    /**
     * Create new records
     */
    async create(
        model: string,
        values: Record<string, unknown>
    ): Promise<number> {
        const response = await this.call<number>(model, 'create', [values]);
        return response.result || 0;
    }

    /**
     * Update existing records
     */
    async write(
        model: string,
        ids: number[],
        values: Record<string, unknown>
    ): Promise<boolean> {
        const response = await this.call<boolean>(model, 'write', [ids, values]);
        return response.result || false;
    }

    /**
     * Delete records
     */
    async unlink(
        model: string,
        ids: number[]
    ): Promise<boolean> {
        const response = await this.call<boolean>(model, 'unlink', [ids]);
        return response.result || false;
    }

    /**
     * Check if current user belongs to a security group (by XMLID)
     */
    async hasGroup(xmlId: string): Promise<boolean> {
        try {
            const uid = await this.getUserId();
            // Call has_group on res.users for the specific UID
            const response = await this.call<boolean>('res.users', 'has_group', [xmlId], {
                context: { uid: uid }
            });
            return response.result || false;
        } catch (error) {
            console.error(`Error checking group ${xmlId}:`, error);
            return false;
        }
    }

    /**
     * Logout from Odoo
     */
    async logout(): Promise<boolean> {
        try {
            await fetch(`${this.baseUrl}/web/session/destroy`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                credentials: 'include',
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {},
                    id: Math.floor(Math.random() * 1000000),
                }),
            });

            this.sessionId = null;
            this.uid = 0;
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Get current session ID
     */
    getSessionId(): string | null {
        return this.sessionId;
    }

    /**
     * Set session ID (for restoring session)
     */
    setSessionId(sessionId: string): void {
        this.sessionId = sessionId;
    }

    /**
     * Get current user ID, fetching from session if necessary
     */
    async getUserId(): Promise<number> {
        if (this.uid) {
            return this.uid;
        }

        const sessionInfo = await this.checkSession();
        if (sessionInfo.valid && sessionInfo.session?.uid && typeof sessionInfo.session.uid === 'number') {
            this.uid = sessionInfo.session.uid;
            return this.uid;
        }

        throw new Error("Invalid session or missing user ID");
    }

    /**
     * Call an Odoo model method without requiring authentication
     * Used for public endpoints like passkey authentication
     */
    async callMethod<T>(
        model: string,
        method: string,
        args: unknown[] = []
    ): Promise<T> {
        const response = await this.jsonRpc<T>('/web/dataset/call_kw', {
            model: model,
            method: method,
            args: args,
            kwargs: {},
        });

        if (response.error) {
            throw new Error(response.error.message || 'RPC call failed');
        }

        return response.result as T;
    }

    /**
     * Call an Odoo JSON-RPC controller endpoint (type='json').
     * Unlike call_kw, these endpoints can use sudo() internally,
     * making them safe for portal users.
     */
    async callController<T>(
        endpoint: string,
        params: Record<string, unknown> = {}
    ): Promise<T> {
        const headers: Record<string, string> = {
            'Content-Type': 'application/json',
        };

        if (this.sessionId) {
            headers['Cookie'] = `session_id=${this.sessionId}`;
        }

        const response = await fetch(`${this.baseUrl}${endpoint}`, {
            method: 'POST',
            headers,
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params,
                id: Math.floor(Math.random() * 1000000),
            }),
        });

        const data = await response.json();

        if (data.error) {
            const errMsg =
                data.error.data?.message ||
                data.error.message ||
                'Controller call failed';
            throw new Error(errMsg);
        }

        return data.result as T;
    }

    /**
     * Authenticate with a token (for passkey login)
     * This creates a session for the given user
     */
    async authenticateWithToken(
        userId: number,
        token: string
    ): Promise<{ success: boolean; session_id?: string; error?: string }> {
        try {
            // Call the custom authentication endpoint
            const response = await fetch(`${this.baseUrl}/web/session/authenticate_token`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                credentials: 'include',
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        db: this.db,
                        user_id: userId,
                        token: token,
                    },
                    id: Math.floor(Math.random() * 1000000),
                }),
            });

            const data = await response.json();

            if (data.error) {
                return {
                    success: false,
                    error: data.error.data?.message || data.error.message || 'Token authentication failed',
                };
            }

            if (data.result && data.result.uid) {
                // Store session ID
                const setCookie = response.headers.get('set-cookie');
                if (setCookie) {
                    const sessionMatch = setCookie.match(/session_id=([^;]+)/);
                    if (sessionMatch) {
                        this.sessionId = sessionMatch[1];
                    }
                }

                if (typeof data.result.uid === 'number') {
                    this.uid = data.result.uid;
                }

                return {
                    success: true,
                    session_id: this.sessionId || '',
                };
            }

            return {
                success: false,
                error: 'Authentication failed',
            };
        } catch (error) {
            return {
                success: false,
                error: error instanceof Error ? error.message : 'Network error',
            };
        }
    }
}

