export const odooClient = new OdooClient();

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

/**
 * Next.js Middleware for server-side auth redirect.
 * Replaces the client-side redirect in page.tsx, eliminating
 * the need to download JS before deciding where to go.
 */
export function middleware(request: NextRequest) {
    const sessionId = request.cookies.get('odoo_session_id')?.value;
    const { pathname } = request.nextUrl;

    // Public routes that don't need auth
    const publicPaths = ['/login', '/daftar', '/bantuan', '/privacy', '/support', '/api', '/pendeta'];
    if (publicPaths.some(p => pathname.startsWith(p))) {
        return NextResponse.next();
    }

    // Root page redirect — instant, no JS needed
    if (pathname === '/') {
        if (sessionId) {
            return NextResponse.redirect(new URL('/dashboard', request.url));
        }
        return NextResponse.redirect(new URL('/login', request.url));
    }

    // Protected routes: no session cookie → redirect to login
    if (!sessionId) {
        const loginUrl = new URL('/login', request.url);
        loginUrl.searchParams.set('redirect', pathname);
        return NextResponse.redirect(loginUrl);
    }

    return NextResponse.next();
}

export const config = {
    matcher: [
        /*
         * Match all request paths except:
         * - _next/static (static files)
         * - _next/image (image optimization)
         * - favicon, logo, images
         * - API routes (handled separately)
         */
        '/((?!_next/static|_next/image|favicon|logo|.*\\.png$|.*\\.ico$).*)',
    ],
};

'use client';

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { OdooUser } from '@/types/odoo';

interface AuthContextType {
    user: OdooUser | null;
    isLoading: boolean;
    isAuthenticated: boolean;
    login: (username: string, password: string) => Promise<{ success: boolean; error?: string }>;
    logout: () => Promise<void>;
    checkAuth: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<OdooUser | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    const checkAuth = useCallback(async () => {
        try {
            const response = await fetch('/api/auth/session');
            const data = await response.json();

            if (data.success && data.user) {
                setUser(data.user);
            } else {
                setUser(null);
            }
        } catch {
            setUser(null);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        checkAuth();
    }, [checkAuth]);

    const login = async (username: string, password: string) => {
        setIsLoading(true);
        try {
            const response = await fetch('/api/auth/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ username, password }),
            });

            const data = await response.json();

            if (data.success && data.user) {
                setUser(data.user);
                return { success: true };
            }

            return { success: false, error: data.error || 'Login failed' };
        } catch (error) {
            return {
                success: false,
                error: error instanceof Error ? error.message : 'Network error'
            };
        } finally {
            setIsLoading(false);
        }
    };

    const logout = async () => {
        setIsLoading(true);
        try {
            await fetch('/api/auth/logout', {
                method: 'POST',
            });
            setUser(null);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <AuthContext.Provider
            value={{
                user,
                isLoading,
                isAuthenticated: !!user,
                login,
                logout,
                checkAuth,
            }}
        >
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

// Odoo Session Response
export interface OdooSession {
    uid: number | false;
    session_id: string;
    db: string;
    username: string;
    name: string;
    partner_id: number;
    company_id: number;
    user_context: Record<string, unknown>;
}

// Authentication Response
export interface OdooAuthResponse {
    jsonrpc: string;
    id: number | null;
    result?: OdooSession;
    error?: {
        code: number;
        message: string;
        data: {
            name: string;
            debug: string;
            message: string;
            arguments: string[];
        };
    };
}

// Generic JSON-RPC Response
export interface OdooRpcResponse<T = unknown> {
    jsonrpc: string;
    id: number | null;
    result?: T;
    error?: {
        code: number;
        message: string;
        data: {
            name: string;
            debug: string;
            message: string;
            arguments: string[];
        };
    };
}

// User data stored in context
export interface OdooUser {
    uid: number;
    name: string;
    username: string;
    partnerId: number;
    companyId: number;
    sessionId: string;
}

// Login credentials
export interface LoginCredentials {
    username: string;
    password: string;
}

// API Response wrapper
export interface ApiResponse<T = unknown> {
    success: boolean;
    data?: T;
    error?: string;
}

export interface FiscalYear {
    id: number;
    name: string;
    date_from: string;
    date_to: string;
    state: string;
}

export interface JemaatMeasureValue {
    id: number;
    measure_id: [number, string]; // [id, name]
    measure_name: string;
    measure_code: string;
    measure_type: 'float' | 'integer' | 'text' | 'date' | 'datetime' | 'boolean' | 'selection' | 'rate' | 'table';
    measure_description?: string | false; // Optional description
    value_float: number;
    value_int: number;
    value_text: string | boolean; // Odoo text fields sometimes return false if empty
    value_boolean: boolean;
    value_json: Record<string, unknown>[] | false; // Array of row objects for table type
    value_int_prev: number;
    value_int_percent_prev: number;
    measure_is_auto_calculate: boolean;
    measure_is_section?: boolean;
