import { NextResponse } from 'next/server';
import { OdooClient } from '@/lib/odoo';
import { cookies } from 'next/headers';

/**
 * GET /api/user/roles
 * Returns the user's roles for accessible jemaats, klasis, sinode wilayah, and sinode
 */
export async function GET(request: Request) {
    const cookieStore = await cookies();
    const session_id = cookieStore.get("odoo_session_id")?.value;

    if (!session_id) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const requestedJemaatId = searchParams.get('jemaatId');

    const odoo = new OdooClient();
    odoo.setSessionId(session_id);

    try {
        const userId = await odoo.getUserId();

        // Domain templates for each role type at all hierarchy levels (for Jemaat)
        const adminDomain = [
            '|', '|', '|',
            ['admin_user_ids', 'in', [userId]],
            ['klasis_id.admin_user_ids', 'in', [userId]],
            ['sinodewilayah_id.admin_user_ids', 'in', [userId]],
            ['sinode_id.admin_user_ids', 'in', [userId]],
        ];

        const financeDomain = [
            '|', '|', '|',
            ['finance_user_ids', 'in', [userId]],
            ['klasis_id.finance_user_ids', 'in', [userId]],
            ['sinodewilayah_id.finance_user_ids', 'in', [userId]],
            ['sinode_id.finance_user_ids', 'in', [userId]],
        ];

        const profileDomain = [
            '|', '|', '|',
            ['profile_user_ids', 'in', [userId]],
            ['klasis_id.profile_user_ids', 'in', [userId]],
            ['sinodewilayah_id.profile_user_ids', 'in', [userId]],
            ['sinode_id.profile_user_ids', 'in', [userId]],
        ];

        // Apply jemaatId filter if specified
        let adminDomainFinal: any[] = adminDomain;
        let financeDomainFinal: any[] = financeDomain;
        let profileDomainFinal: any[] = profileDomain;

        if (requestedJemaatId) {
            const idFilter = ['id', '=', parseInt(requestedJemaatId)];
            adminDomainFinal = ['&', idFilter, ...adminDomain];
            financeDomainFinal = ['&', idFilter, ...financeDomain];
            profileDomainFinal = ['&', idFilter, ...profileDomain];
        }

        // Klasis access domains - check direct access AND inherited from Sinode Wilayah and Sinode
        const klasisAdminDomain = [
            '|', '|',
            ['admin_user_ids', 'in', [userId]],
            ['sinodewilayah_id.admin_user_ids', 'in', [userId]],
            ['sinodewilayah_id.sinode_id.admin_user_ids', 'in', [userId]],
        ];
        const klasisFinanceDomain = [
            '|', '|',
            ['finance_user_ids', 'in', [userId]],
            ['sinodewilayah_id.finance_user_ids', 'in', [userId]],
            ['sinodewilayah_id.sinode_id.finance_user_ids', 'in', [userId]],
        ];
        const klasisProfileDomain = [
            '|', '|',
            ['profile_user_ids', 'in', [userId]],
            ['sinodewilayah_id.profile_user_ids', 'in', [userId]],
            ['sinodewilayah_id.sinode_id.profile_user_ids', 'in', [userId]],
        ];

        // Sinode Wilayah access domains - check direct access AND inherited from Sinode
        const sinodewilayahAdminDomain = [
            '|',
            ['admin_user_ids', 'in', [userId]],
            ['sinode_id.admin_user_ids', 'in', [userId]],
        ];
        const sinodewilayahFinanceDomain = [
            '|',
            ['finance_user_ids', 'in', [userId]],
            ['sinode_id.finance_user_ids', 'in', [userId]],
        ];
        const sinodewilayahProfileDomain = [
            '|',
            ['profile_user_ids', 'in', [userId]],
            ['sinode_id.profile_user_ids', 'in', [userId]],
        ];

        // Sinode access domains - direct access only (top level)
        const sinodeAdminDomain = [['admin_user_ids', 'in', [userId]]];
        const sinodeFinanceDomain = [['finance_user_ids', 'in', [userId]]];
        const sinodeProfileDomain = [['profile_user_ids', 'in', [userId]]];

        // Fetch jemaats for each role type
        const [adminJemaats, financeJemaats, profileJemaats] = await Promise.all([
            odoo.searchRead<any>('jemaat.jemaat', adminDomainFinal, ['id', 'name', 'klasis_id', 'sinodewilayah_id']),
            odoo.searchRead<any>('jemaat.jemaat', financeDomainFinal, ['id', 'name', 'klasis_id', 'sinodewilayah_id']),
            odoo.searchRead<any>('jemaat.jemaat', profileDomainFinal, ['id', 'name', 'klasis_id', 'sinodewilayah_id']),
        ]);

        // Fetch Klasis access
        const [adminKlasis, financeKlasis, profileKlasis] = await Promise.all([
            odoo.searchRead<any>('jemaat.klasis', klasisAdminDomain, ['id', 'name', 'sinodewilayah_id']),
            odoo.searchRead<any>('jemaat.klasis', klasisFinanceDomain, ['id', 'name', 'sinodewilayah_id']),
            odoo.searchRead<any>('jemaat.klasis', klasisProfileDomain, ['id', 'name', 'sinodewilayah_id']),
        ]);

        // Fetch Sinode Wilayah access
        const [adminSinodeWilayah, financeSinodeWilayah, profileSinodeWilayah] = await Promise.all([
            odoo.searchRead<any>('jemaat.sinodewilayah', sinodewilayahAdminDomain, ['id', 'name', 'sinode_id']),
            odoo.searchRead<any>('jemaat.sinodewilayah', sinodewilayahFinanceDomain, ['id', 'name', 'sinode_id']),
            odoo.searchRead<any>('jemaat.sinodewilayah', sinodewilayahProfileDomain, ['id', 'name', 'sinode_id']),
        ]);

        // Fetch Sinode access
        const [adminSinode, financeSinode, profileSinode] = await Promise.all([
            odoo.searchRead<any>('jemaat.sinode', sinodeAdminDomain, ['id', 'name']),
            odoo.searchRead<any>('jemaat.sinode', sinodeFinanceDomain, ['id', 'name']),
            odoo.searchRead<any>('jemaat.sinode', sinodeProfileDomain, ['id', 'name']),
        ]);

        // Check for SDM Gereja groups
        const [isSdmUser, isSdmManager, isSdmConfidential] = await Promise.all([
            odoo.hasGroup('church_hr.group_church_hr_user'),
            odoo.hasGroup('church_hr.group_church_hr_manager'),
            odoo.hasGroup('church_hr.group_church_hr_confidential'),
        ]);

        const isAdmin = adminJemaats.length > 0;
        const isFinance = financeJemaats.length > 0;
        const isProfile = profileJemaats.length > 0;

        const hasKlasisAccess = adminKlasis.length > 0 || financeKlasis.length > 0 || profileKlasis.length > 0;
        const hasSinodeWilayahAccess = adminSinodeWilayah.length > 0 || financeSinodeWilayah.length > 0 || profileSinodeWilayah.length > 0;
        const hasSinodeAccess = adminSinode.length > 0 || financeSinode.length > 0 || profileSinode.length > 0;

        // Build detailed jemaat access list with roles
        const jemaatRolesMap = new Map<number, { id: number; name: string; klasis: string; roles: string[] }>();

        for (const j of adminJemaats) {
            if (!jemaatRolesMap.has(j.id)) {
                jemaatRolesMap.set(j.id, {
                    id: j.id,
                    name: j.name,
                    klasis: j.klasis_id ? j.klasis_id[1] : '-',
                    roles: [],
                });
            }
            jemaatRolesMap.get(j.id)!.roles.push('Admin');
        }

        for (const j of financeJemaats) {
            if (!jemaatRolesMap.has(j.id)) {
                jemaatRolesMap.set(j.id, {
                    id: j.id,
                    name: j.name,
                    klasis: j.klasis_id ? j.klasis_id[1] : '-',
                    roles: [],
                });
            }
            const entry = jemaatRolesMap.get(j.id)!;
            if (!entry.roles.includes('Keuangan')) {
                entry.roles.push('Keuangan');
            }
        }

        for (const j of profileJemaats) {
            if (!jemaatRolesMap.has(j.id)) {
                jemaatRolesMap.set(j.id, {
                    id: j.id,
                    name: j.name,
                    klasis: j.klasis_id ? j.klasis_id[1] : '-',
                    roles: [],
                });
            }
            const entry = jemaatRolesMap.get(j.id)!;
            if (!entry.roles.includes('Profil')) {
                entry.roles.push('Profil');
            }
        }

        // Build Klasis access list
        const klasisRolesMap = new Map<number, { id: number; name: string; sinodewilayah: string; roles: string[] }>();
        for (const k of adminKlasis) {
            if (!klasisRolesMap.has(k.id)) {
                klasisRolesMap.set(k.id, { id: k.id, name: k.name, sinodewilayah: k.sinodewilayah_id ? k.sinodewilayah_id[1] : '-', roles: [] });
            }
            klasisRolesMap.get(k.id)!.roles.push('Admin');
        }
        for (const k of financeKlasis) {
            if (!klasisRolesMap.has(k.id)) {
                klasisRolesMap.set(k.id, { id: k.id, name: k.name, sinodewilayah: k.sinodewilayah_id ? k.sinodewilayah_id[1] : '-', roles: [] });
            }
            const entry = klasisRolesMap.get(k.id)!;
            if (!entry.roles.includes('Keuangan')) entry.roles.push('Keuangan');
        }
        for (const k of profileKlasis) {
            if (!klasisRolesMap.has(k.id)) {
                klasisRolesMap.set(k.id, { id: k.id, name: k.name, sinodewilayah: k.sinodewilayah_id ? k.sinodewilayah_id[1] : '-', roles: [] });
            }
            const entry = klasisRolesMap.get(k.id)!;
            if (!entry.roles.includes('Profil')) entry.roles.push('Profil');
        }

        // Build Sinode Wilayah access list
        const sinodewilayahRolesMap = new Map<number, { id: number; name: string; sinode: string; roles: string[] }>();
        for (const s of adminSinodeWilayah) {
            if (!sinodewilayahRolesMap.has(s.id)) {
                sinodewilayahRolesMap.set(s.id, { id: s.id, name: s.name, sinode: s.sinode_id ? s.sinode_id[1] : '-', roles: [] });
            }
            sinodewilayahRolesMap.get(s.id)!.roles.push('Admin');
        }
        for (const s of financeSinodeWilayah) {
            if (!sinodewilayahRolesMap.has(s.id)) {
                sinodewilayahRolesMap.set(s.id, { id: s.id, name: s.name, sinode: s.sinode_id ? s.sinode_id[1] : '-', roles: [] });
            }
            const entry = sinodewilayahRolesMap.get(s.id)!;
            if (!entry.roles.includes('Keuangan')) entry.roles.push('Keuangan');
        }
        for (const s of profileSinodeWilayah) {
            if (!sinodewilayahRolesMap.has(s.id)) {
                sinodewilayahRolesMap.set(s.id, { id: s.id, name: s.name, sinode: s.sinode_id ? s.sinode_id[1] : '-', roles: [] });
            }
            const entry = sinodewilayahRolesMap.get(s.id)!;
            if (!entry.roles.includes('Profil')) entry.roles.push('Profil');
        }

        // Build Sinode access list
        const sinodeRolesMap = new Map<number, { id: number; name: string; roles: string[] }>();
        for (const s of adminSinode) {
            if (!sinodeRolesMap.has(s.id)) {
                sinodeRolesMap.set(s.id, { id: s.id, name: s.name, roles: [] });
            }
            sinodeRolesMap.get(s.id)!.roles.push('Admin');
        }
        for (const s of financeSinode) {
            if (!sinodeRolesMap.has(s.id)) {
                sinodeRolesMap.set(s.id, { id: s.id, name: s.name, roles: [] });
            }
            const entry = sinodeRolesMap.get(s.id)!;
            if (!entry.roles.includes('Keuangan')) entry.roles.push('Keuangan');
        }
        for (const s of profileSinode) {
            if (!sinodeRolesMap.has(s.id)) {
                sinodeRolesMap.set(s.id, { id: s.id, name: s.name, roles: [] });
            }
            const entry = sinodeRolesMap.get(s.id)!;
            if (!entry.roles.includes('Profil')) entry.roles.push('Profil');
        }

        const jemaatAccessList = Array.from(jemaatRolesMap.values()).sort((a, b) => a.name.localeCompare(b.name));
        const klasisAccessList = Array.from(klasisRolesMap.values()).sort((a, b) => a.name.localeCompare(b.name));
        const sinodewilayahAccessList = Array.from(sinodewilayahRolesMap.values()).sort((a, b) => a.name.localeCompare(b.name));
        const sinodeAccessList = Array.from(sinodeRolesMap.values()).sort((a, b) => a.name.localeCompare(b.name));

        return NextResponse.json({
            roles: {
                isAdmin,
                isFinance,
                isProfile,
                isSdmUser,
                isSdmManager,
                isSdmConfidential,
            },
            jemaatCount: jemaatAccessList.length,
            jemaatAccess: jemaatAccessList,
            klasisCount: klasisAccessList.length,
            klasisAccess: klasisAccessList,
            sinodewilayahCount: sinodewilayahAccessList.length,
            sinodewilayahAccess: sinodewilayahAccessList,
            sinodeCount: sinodeAccessList.length,
            sinodeAccess: sinodeAccessList,
            access: {
                dashboard: isAdmin || isFinance || isProfile,
                profile: isAdmin || isProfile,
                purj: isAdmin || isProfile,
                finance: isAdmin || isFinance,
                asset: isAdmin || isProfile,
                elearning: true,  // eLearning is accessible to all authenticated users
                myprofile: true,  // Personal profile accessible to all authenticated users
                sdm_gereja: isSdmUser || isSdmManager, // Access to SDM Gereja module
                anggota: isAdmin || isProfile,
                analitik: isAdmin || isFinance,
                forum: true,  // Forum is accessible to all authenticated users
                messages: true,  // Messages is accessible to all authenticated users
                kelola_klasis: hasKlasisAccess,
                kelola_sinodewilayah: hasSinodeWilayahAccess,
                kelola_sinode: hasSinodeAccess,
            }
        });

    } catch (error: any) {
        console.error("Error fetching user roles:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { cookies } from "next/headers";

const ODOO_URL = process.env.ODOO_URL || process.env.NEXT_PUBLIC_ODOO_URL || 'https://demo18.infinia.id';

export async function GET(request: Request) {
    const cookieStore = await cookies();
    const session_id = cookieStore.get("odoo_session_id")?.value;

    if (!session_id) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const fiscalyear_id = searchParams.get("fiscalyear_id");

    if (!fiscalyear_id) {
        return NextResponse.json({ error: "fiscalyear_id is required" }, { status: 400 });
    }

    // Build query string for Odoo REST API
    const queryParts: string[] = [];
    const klasis_id = searchParams.get("klasis_id");
    const sinodewilayah_id = searchParams.get("sinodewilayah_id");
    const state = searchParams.get("state");
    if (klasis_id) queryParts.push(`klasis_id=${klasis_id}`);
    if (sinodewilayah_id) queryParts.push(`sinodewilayah_id=${sinodewilayah_id}`);
    if (state) queryParts.push(`state=${state}`);

    const qs = queryParts.length > 0 ? `?${queryParts.join("&")}` : "";
    const url = `${ODOO_URL}/api/v1/evaluation/dashboard/${fiscalyear_id}${qs}`;

    try {
        const response = await fetch(url, {
            headers: {
                "Cookie": `session_id=${session_id}`,
                "Accept": "application/json",
            },
            cache: "no-store",
        });

        if (!response.ok) {
            const text = await response.text();
            console.error("[Dashboard API] Odoo error:", response.status, text);
            return NextResponse.json(
                { error: "Failed to fetch dashboard data" },
                { status: response.status }
            );
        }

        const data = await response.json();
        return NextResponse.json(data);
    } catch (error: any) {
        console.error("[Dashboard API] Error:", error);
        return NextResponse.json(
            { error: "Failed to fetch dashboard data" },
            { status: 500 }
        );
    }
}

