                    </nav>

                    {/* User section - pinned at bottom */}
                    <div className="flex-shrink-0 p-4 border-t border-gki-gray-100 dark:border-gki-gray-700">
                        <div className={`flex items-center gap-3 ${sidebarOpen ? '' : 'justify-center'}`}>
