                                    <p className="text-xs text-gki-gray-500 dark:text-gki-gray-400 truncate">
                                        {user?.username || ''}
                                    </p>
                                </div>

            odoo.searchRead<any>('jemaat.sinode', sinodeProfileDomain, ['id', 'name']),
        ]);

        // Check for SDM Gereja groups
        const [isSdmUser, isSdmManager, isSdmConfidential] = await Promise.all([
            odoo.hasGroup('church_hr.group_church_hr_user'),
            odoo.hasGroup('church_hr.group_church_hr_manager'),
            odoo.hasGroup('church_hr.group_church_hr_confidential'),
        ]);

        const isAdmin = adminJemaats.length > 0;
        const isFinance = financeJemaats.length > 0;
        const isProfile = profileJemaats.length > 0;

        const hasKlasisAccess = adminKlasis.length > 0 || financeKlasis.length > 0 || profileKlasis.length > 0;
        const hasSinodeWilayahAccess = adminSinodeWilayah.length > 0 || financeSinodeWilayah.length > 0 || profileSinodeWilayah.length > 0;
        const hasSinodeAccess = adminSinode.length > 0 || financeSinode.length > 0 || profileSinode.length > 0;

        // Build detailed jemaat access list with roles
        const jemaatRolesMap = new Map<number, { id: number; name: string; klasis: string; roles: string[] }>();

        for (const j of adminJemaats) {
            if (!jemaatRolesMap.has(j.id)) {
                jemaatRolesMap.set(j.id, {
                    id: j.id,
                    name: j.name,
                    klasis: j.klasis_id ? j.klasis_id[1] : '-',
                    roles: [],
                });
            }
            jemaatRolesMap.get(j.id)!.roles.push('Admin');
