    const router = useRouter();
    const pathname = usePathname();
    const { user, isAuthenticated, isLoading, logout } = useAuth();
    const [sidebarOpen, setSidebarOpen] = useState(true);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [userAccess, setUserAccess] = useState<UserAccess | null>(null);
    const [expandedMenus, setExpandedMenus] = useState<string[]>(['Dashboard']);
    const [onboardingComplete, setOnboardingComplete] = useState<boolean | null>(null);
    const [notifUnread, setNotifUnread] = useState(0);
    const [notifOpen, setNotifOpen] = useState(false);
    const [notifItems, setNotifItems] = useState<any[]>([]);
    const [notifLoading, setNotifLoading] = useState(false);

    // Toggle menu expansion
    const toggleMenu = (menuName: string) => {
        setExpandedMenus(prev =>
            prev.includes(menuName)
                ? prev.filter(m => m !== menuName)
                : [...prev, menuName]
        );
    };

    // Fetch notification unread count
    useEffect(() => {
        async function fetchNotifCount() {
            try {
                const res = await fetch('/api/notifications', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ limit: 1 }) });
                const d = await res.json();
                if (d.success) setNotifUnread(d.unread || 0);
            } catch {}
        }
        fetchNotifCount();
        const interval = setInterval(fetchNotifCount, 60000); // poll every minute
        return () => clearInterval(interval);
    }, []);

    // Fetch user roles on mount
    useEffect(() => {
        async function fetchUserRoles() {
            try {
                const response = await fetch('/api/user/roles');
                if (response.ok) {
                    const data = await response.json();
                    setUserAccess(data.access);
                }
            } catch (error) {
                console.error('Failed to fetch user roles:', error);
                // Default to showing all menus if roles API fails
                setUserAccess({
                    dashboard: true,
                    profile: true,
                    purj: true,
                    finance: true,
                    asset: true,
                    elearning: true,
                    myprofile: true,
                    sdm_gereja: false,
                    anggota: true,
                    analitik: true,
                    forum: true,
                    messages: true,
                    kelola_klasis: false,
                    kelola_sinodewilayah: false,
                    kelola_sinode: false,
                });
            }
        }
        if (isAuthenticated) {
            fetchUserRoles();
        }
    }, [isAuthenticated]);

    useEffect(() => {
        if (!isLoading && !isAuthenticated) {
            router.replace('/login');
        }
    }, [isAuthenticated, isLoading, router]);

    // Check onboarding status based on minimum profile completeness
    useEffect(() => {
        async function checkOnboarding() {
            if (pathname === '/onboarding') {
                setOnboardingComplete(false);
                return;
            }
            // If user already skipped onboarding in this session, don't redirect
            if (typeof window !== 'undefined' && sessionStorage.getItem('onboarding_skipped')) {
                setOnboardingComplete(true);
                return;
            }
            try {
                const res = await fetch('/api/user/onboarding');
                const data = await res.json();
                if (data.success) {
                    // If no employee data, skip onboarding (user is not linked to employee)
                    if (!data.data) {
                        setOnboardingComplete(true);
                        return;
                    }
                    if (data.onboarding) {
                        const complete = data.onboarding.is_onboarding_complete;
                        setOnboardingComplete(complete);
                        if (!complete) {
                            router.replace('/onboarding');
                        }
                    } else {
                        setOnboardingComplete(true);
                    }
                } else {
                    setOnboardingComplete(true);
                }
            } catch {
                setOnboardingComplete(true);
            }
        }
        if (isAuthenticated) {
            checkOnboarding();
        }
    }, [isAuthenticated, pathname, router]);

    const handleLogout = async () => {
        await logout();
        router.replace('/login');
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gki-gray-50 dark:bg-gki-gray-900">
                <div className="w-16 h-16 border-4 border-gki-blue/30 border-t-gki-blue rounded-full animate-spin" />
            </div>
        );
    }

    if (!isAuthenticated) {
        return null;
    }

    // Onboarding page gets a clean layout (no sidebar)
    if (pathname === '/onboarding') {
        return <>{children}</>;
    }

    return (
