                                            const res = await fetch('/api/notifications', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ limit: 10 }) });
                                            const d = await res.json();
                                            if (d.success) { setNotifItems(d.data || []); setNotifUnread(d.unread || 0); }
                                        } catch {} finally { setNotifLoading(false); }
                                    }
                                }}
                                className="relative p-2 rounded-lg text-gki-gray-600 dark:text-gki-gray-300 hover:bg-gki-gray-100 dark:hover:bg-gki-gray-700 transition-colors"
                                title="Notifikasi"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
                                </svg>
                                {notifUnread > 0 && (
                                    <span className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center animate-pulse">
                                        {notifUnread > 9 ? '9+' : notifUnread}
                                    </span>
                                )}
                            </button>
                            {notifOpen && (
                                <>
                                    <div className="fixed inset-0 z-40" onClick={() => setNotifOpen(false)} />
                                    <div className="absolute right-0 top-full mt-2 w-80 bg-white dark:bg-gki-gray-800 rounded-xl shadow-xl border border-gki-gray-100 dark:border-gki-gray-700 z-50 overflow-hidden">
