                                                }} className="text-xs text-gki-blue hover:underline">Tandai semua dibaca</button>
                                            )}
                                        </div>
                                        <div className="max-h-72 overflow-y-auto">
                                            {notifLoading ? (
                                                <div className="p-6 text-center"><div className="animate-spin w-5 h-5 border-2 border-gki-blue border-t-transparent rounded-full mx-auto" /></div>
                                            ) : notifItems.length === 0 ? (
                                                <div className="p-6 text-center text-gki-gray-400"><span className="text-2xl block mb-1">🔕</span><p className="text-xs">Belum ada notifikasi</p></div>
                                            ) : (
                                                notifItems.map((n: any) => (
                                                    <a key={n.id} href={n.link || '#'} onClick={() => setNotifOpen(false)} className={`flex gap-3 px-4 py-3 hover:bg-gki-gray-50 dark:hover:bg-gki-gray-750 transition-colors border-b border-gki-gray-50 dark:border-gki-gray-700 ${!n.is_read ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}>
                                                        <span className="text-lg flex-shrink-0">{n.icon}</span>
                                                        <div className="flex-1 min-w-0">
                                                            <p className={`text-sm leading-snug ${!n.is_read ? 'font-semibold text-gki-gray-900 dark:text-white' : 'text-gki-gray-600 dark:text-gray-400'}`}>{n.title}</p>
