/* ─── Floating Scroll Buttons ─── */
function ScrollButtons() {
    const [showTop, setShowTop] = useState(false);
    const [showBottom, setShowBottom] = useState(false);

    const checkScroll = useCallback(() => {
        const scrollY = window.scrollY;
        const docH = document.documentElement.scrollHeight;
        const winH = window.innerHeight;
        setShowTop(scrollY > 300);
        setShowBottom(scrollY + winH < docH - 200);
    }, []);

    useEffect(() => {
        checkScroll();
        window.addEventListener('scroll', checkScroll, { passive: true });
        window.addEventListener('resize', checkScroll, { passive: true });
        return () => {
            window.removeEventListener('scroll', checkScroll);
            window.removeEventListener('resize', checkScroll);
        };
    }, [checkScroll]);

    const scrollTo = (pos: 'top' | 'bottom') => {
        window.scrollTo({ top: pos === 'top' ? 0 : document.documentElement.scrollHeight, behavior: 'smooth' });
    };

    if (!showTop && !showBottom) return null;

    return (
        <div className="fixed bottom-6 right-6 flex flex-col gap-2 z-40">
            {showTop && (
                <button
                    onClick={() => scrollTo('top')}
                    className="w-9 h-9 rounded-full bg-white dark:bg-gki-gray-700 shadow-lg border border-gray-200 dark:border-gki-gray-600 flex items-center justify-center text-gray-500 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gki-gray-600 hover:text-gki-blue transition-all hover:scale-110"
                    title="Ke atas"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                </button>
            )}
            {showBottom && (
                <button
                    onClick={() => scrollTo('bottom')}
                    className="w-9 h-9 rounded-full bg-white dark:bg-gki-gray-700 shadow-lg border border-gray-200 dark:border-gki-gray-600 flex items-center justify-center text-gray-500 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gki-gray-600 hover:text-gki-blue transition-all hover:scale-110"
                    title="Ke bawah"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                </button>
            )}
        </div>
    );
}

