                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </button>

                        {/* Notification Bell */}
                        <div className="relative">
                            <button
                                onClick={async () => {
                                    setNotifOpen(!notifOpen);
                                    if (!notifOpen && notifItems.length === 0) {
                                        setNotifLoading(true);
                                        try {
                                            const res = await fetch('/api/notifications', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ limit: 10 }) });
                                            const d = await res.json();
                                            if (d.success) { setNotifItems(d.data || []); setNotifUnread(d.unread || 0); }
                                        } catch {} finally { setNotifLoading(false); }
                                    }
                                }}
                                className="relative p-2 rounded-lg text-gki-gray-600 dark:text-gki-gray-300 hover:bg-gki-gray-100 dark:hover:bg-gki-gray-700 transition-colors"
                                title="Notifikasi"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
                                </svg>
                                {notifUnread > 0 && (
                                    <span className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center animate-pulse">
                                        {notifUnread > 9 ? '9+' : notifUnread}
                                    </span>
                                )}
                            </button>
                            {notifOpen && (
                                <>
                                    <div className="fixed inset-0 z-40" onClick={() => setNotifOpen(false)} />
                                    <div className="absolute right-0 top-full mt-2 w-80 bg-white dark:bg-gki-gray-800 rounded-xl shadow-xl border border-gki-gray-100 dark:border-gki-gray-700 z-50 overflow-hidden">
                                        <div className="px-4 py-3 border-b border-gki-gray-100 dark:border-gki-gray-700 flex items-center justify-between">
                                            <h3 className="font-semibold text-gki-gray-900 dark:text-white text-sm">🔔 Notifikasi</h3>
                                            {notifUnread > 0 && (
                                                <button onClick={async () => {
                                                    await fetch('/api/notifications', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'mark-read', mark_all: true }) });
                                                    setNotifUnread(0); setNotifItems(prev => prev.map(n => ({ ...n, is_read: true })));
                                                }} className="text-xs text-gki-blue hover:underline">Tandai semua dibaca</button>
                                            )}
                                        </div>
                                        <div className="max-h-72 overflow-y-auto">
                                            {notifLoading ? (
                                                <div className="p-6 text-center"><div className="animate-spin w-5 h-5 border-2 border-gki-blue border-t-transparent rounded-full mx-auto" /></div>
                                            ) : notifItems.length === 0 ? (
                                                <div className="p-6 text-center text-gki-gray-400"><span className="text-2xl block mb-1">🔕</span><p className="text-xs">Belum ada notifikasi</p></div>
                                            ) : (
                                                notifItems.map((n: any) => (
                                                    <a key={n.id} href={n.link || '#'} onClick={() => setNotifOpen(false)} className={`flex gap-3 px-4 py-3 hover:bg-gki-gray-50 dark:hover:bg-gki-gray-750 transition-colors border-b border-gki-gray-50 dark:border-gki-gray-700 ${!n.is_read ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}>
                                                        <span className="text-lg flex-shrink-0">{n.icon}</span>
                                                        <div className="flex-1 min-w-0">
                                                            <p className={`text-sm leading-snug ${!n.is_read ? 'font-semibold text-gki-gray-900 dark:text-white' : 'text-gki-gray-600 dark:text-gray-400'}`}>{n.title}</p>
                                                            {n.body && <p className="text-xs text-gki-gray-400 mt-0.5 line-clamp-1">{n.body}</p>}
                                                        </div>
                                                        {!n.is_read && <div className="w-2 h-2 bg-gki-blue rounded-full flex-shrink-0 mt-1.5" />}
                                                    </a>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                </>
                            )}
                        </div>

                        {/* Dynamic Context Selector - shows appropriate selector based on URL */}
                        <DynamicContextSelector pathname={pathname} />
                    </div>
                </header>

                {/* Page content */}
                <main className="p-4 lg:p-6">
                    {children}
                </main>

                {/* Floating scroll buttons */}
                <ScrollButtons />
            </div>
        </div>
    );
}

// Jemaat Selector Component
function JemaatSelector() {
    const { jemaatList, fullJemaatList, selectedJemaatId, setSelectedJemaatId, isLoading } = useJemaat();

    if (isLoading) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-gki-gray-100 dark:bg-gki-gray-700 rounded-lg">
                <div className="w-4 h-4 border-2 border-gki-gray-300 border-t-gki-blue rounded-full animate-spin" />
                <span className="text-xs text-gki-gray-400">Loading...</span>
            </div>
        );
    }

    if (jemaatList.length === 0) {
        return null;
    }

    if (jemaatList.length === 1) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-gki-gray-100 dark:bg-gki-gray-700 rounded-lg">
                <svg className="w-4 h-4 text-gki-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
                <span className="text-sm font-medium text-gki-gray-700 dark:text-gray-200">
                    {jemaatList[0].name}
                </span>
            </div>
        );
    }

    // Group jemaat by klasis
    const grouped = fullJemaatList.reduce<Record<string, { klasisName: string; jemaats: { id: number; name: string }[] }>>((acc, j) => {
        const klasisKey = j.klasis_id ? String(j.klasis_id[0]) : '_none';
        const klasisName = j.klasis_id ? j.klasis_id[1] : 'Lainnya';
        if (!acc[klasisKey]) {
            acc[klasisKey] = { klasisName, jemaats: [] };
        }
        acc[klasisKey].jemaats.push({ id: j.id, name: j.name });
        return acc;
    }, {});

    // Sort klasis groups alphabetically, put "Lainnya" last
    const sortedGroups = Object.entries(grouped).sort(([keyA, a], [keyB, b]) => {
        if (keyA === '_none') return 1;
        if (keyB === '_none') return -1;
        return a.klasisName.localeCompare(b.klasisName);
    });

    // Sort jemaats within each group alphabetically
    sortedGroups.forEach(([, group]) => {
        group.jemaats.sort((a, b) => a.name.localeCompare(b.name));
    });

    const hasMultipleGroups = sortedGroups.length > 1;

    return (
        <div className="flex items-center gap-2">
            <svg className="w-4 h-4 text-gki-gray-500 dark:text-gki-gray-400 hidden sm:block" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
            <select
                value={selectedJemaatId || ''}
                onChange={(e) => setSelectedJemaatId(Number(e.target.value))}
                className="block min-w-[180px] max-w-[280px] rounded-lg border border-gki-gray-200 dark:border-gki-gray-600 bg-white dark:bg-gki-gray-700 py-1.5 pl-3 pr-8 text-sm font-medium text-gki-gray-900 dark:text-white shadow-sm focus:border-gki-blue focus:ring-2 focus:ring-gki-blue/20 focus:outline-none cursor-pointer hover:border-gki-blue/50 transition-colors appearance-none bg-no-repeat bg-right"
                style={{
                    backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`,
                    backgroundPosition: 'right 0.5rem center',
                    backgroundSize: '1.5em 1.5em'
                }}
            >
                {hasMultipleGroups ? (
                    sortedGroups.map(([key, group]) => (
                        <optgroup key={key} label={group.klasisName}>
                            {group.jemaats.map((j) => (
                                <option key={j.id} value={j.id}>
                                    {j.name}
                                </option>
                            ))}
                        </optgroup>
                    ))
                ) : (
                    jemaatList.map((j) => (
                        <option key={j.id} value={j.id}>
                            {j.name}
                        </option>
                    ))
                )}
            </select>
        </div>
    );
}

// Dynamic Context Selector - shows appropriate selector based on URL path
function DynamicContextSelector({ pathname }: { pathname: string }) {
    // Determine which selector to show based on URL path
    if (pathname.startsWith('/klasis')) {
        return <KlasisSelector />;
    }
    if (pathname.startsWith('/sinodewilayah')) {
        return <SinodeWilayahSelector />;
    }
    if (pathname.startsWith('/sinode')) {
        return <SinodeSelector />;
    }
    // SDM pages don't need jemaat filter - they show all data
    if (pathname.startsWith('/sdm')) {
        return null;
    }
    // Default: show Jemaat selector
    return <JemaatSelector />;
}

