                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
                <span className="text-sm font-medium text-indigo-700 dark:text-indigo-300">
                    {sinodeList[0].name}
                </span>
            </div>
        );
    }

    return (
        <div className="flex items-center gap-2">
            <svg className="w-4 h-4 text-indigo-600 dark:text-indigo-400 hidden sm:block" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
            <select
                value={selectedSinodeId || ''}
                onChange={(e) => setSelectedSinodeId(Number(e.target.value))}
                className="block min-w-[180px] max-w-[280px] rounded-lg border border-indigo-200 dark:border-indigo-700 bg-indigo-50 dark:bg-indigo-900/20 py-1.5 pl-3 pr-8 text-sm font-medium text-indigo-900 dark:text-indigo-100 shadow-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 focus:outline-none cursor-pointer hover:border-indigo-400 transition-colors appearance-none bg-no-repeat bg-right"
                style={{
                    backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236366f1' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`,
                    backgroundPosition: 'right 0.5rem center',
                    backgroundSize: '1.5em 1.5em'
                }}
            >
                {sinodeList.map((s) => (
                    <option key={s.id} value={s.id}>
                        {s.name}
                    </option>
                ))}
            </select>
        </div>
    );
}


export default function ProtectedLayoutWrapper({
    children,
}: {
    children: React.ReactNode;
}) {
    return (
        <JemaatProvider>
            <KlasisProvider>
                <SinodeWilayahProvider>
                    <SinodeProvider>
                        <ProtectedLayout>{children}</ProtectedLayout>
                    </SinodeProvider>
                </SinodeWilayahProvider>
            </KlasisProvider>
        </JemaatProvider>
    );
}

