                                            if (d.success) { setNotifItems(d.data || []); setNotifUnread(d.unread || 0); }
                                        } catch {} finally { setNotifLoading(false); }
                                    }
                                }}
                                className="relative p-2 rounded-lg text-gki-gray-600 dark:text-gki-gray-300 hover:bg-gki-gray-100 dark:hover:bg-gki-gray-700 transition-colors"
