function SinodeSelector() {
    const { sinodeList, selectedSinodeId, setSelectedSinodeId, isLoading } = useSinode();

    if (isLoading) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
                <div className="w-4 h-4 border-2 border-indigo-300 border-t-indigo-600 rounded-full animate-spin" />
                <span className="text-xs text-indigo-400">Loading...</span>
            </div>
        );
    }

    if (sinodeList.length === 0) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
