/* ─── Floating Scroll Buttons ─── */
function ScrollButtons() {
    const [showTop, setShowTop] = useState(false);
    const [showBottom, setShowBottom] = useState(false);

    const checkScroll = useCallback(() => {
        const scrollY = window.scrollY;
        const docH = document.documentElement.scrollHeight;
        const winH = window.innerHeight;
        setShowTop(scrollY > 300);
        setShowBottom(scrollY + winH < docH - 200);
    }, []);

    useEffect(() => {
        checkScroll();
        window.addEventListener('scroll', checkScroll, { passive: true });
        window.addEventListener('resize', checkScroll, { passive: true });
        return () => {
            window.removeEventListener('scroll', checkScroll);
            window.removeEventListener('resize', checkScroll);
        };
    }, [checkScroll]);

    const scrollTo = (pos: 'top' | 'bottom') => {
        window.scrollTo({ top: pos === 'top' ? 0 : document.documentElement.scrollHeight, behavior: 'smooth' });
    };

    if (!showTop && !showBottom) return null;

    return (
        <div className="fixed bottom-6 right-6 flex flex-col gap-2 z-40">
            {showTop && (
                <button
                    onClick={() => scrollTo('top')}
                    className="w-9 h-9 rounded-full bg-white dark:bg-gki-gray-700 shadow-lg border border-gray-200 dark:border-gki-gray-600 flex items-center justify-center text-gray-500 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gki-gray-600 hover:text-gki-blue transition-all hover:scale-110"
                    title="Ke atas"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                </button>
            )}
            {showBottom && (
                <button
                    onClick={() => scrollTo('bottom')}
                    className="w-9 h-9 rounded-full bg-white dark:bg-gki-gray-700 shadow-lg border border-gray-200 dark:border-gki-gray-600 flex items-center justify-center text-gray-500 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gki-gray-600 hover:text-gki-blue transition-all hover:scale-110"
                    title="Ke bawah"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                </button>
            )}
        </div>
    );
}

function ProtectedLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    const router = useRouter();
    const pathname = usePathname();
    const { user, isAuthenticated, isLoading, logout } = useAuth();
    const [sidebarOpen, setSidebarOpen] = useState(true);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [userAccess, setUserAccess] = useState<UserAccess | null>(null);
    const [expandedMenus, setExpandedMenus] = useState<string[]>(['Dashboard']);
    const [onboardingComplete, setOnboardingComplete] = useState<boolean | null>(null);
    const [notifUnread, setNotifUnread] = useState(0);
    const [notifOpen, setNotifOpen] = useState(false);
    const [notifItems, setNotifItems] = useState<any[]>([]);
    const [notifLoading, setNotifLoading] = useState(false);

    // Toggle menu expansion
    const toggleMenu = (menuName: string) => {
        setExpandedMenus(prev =>
            prev.includes(menuName)
                ? prev.filter(m => m !== menuName)
                : [...prev, menuName]
        );
    };

    // Fetch notification unread count
    useEffect(() => {
        async function fetchNotifCount() {
            try {
                const res = await fetch('/api/notifications', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ limit: 1 }) });
                const d = await res.json();
                if (d.success) setNotifUnread(d.unread || 0);
            } catch {}
        }
        fetchNotifCount();
        const interval = setInterval(fetchNotifCount, 60000); // poll every minute
        return () => clearInterval(interval);
    }, []);

    // Fetch user roles on mount
    useEffect(() => {
        async function fetchUserRoles() {
            try {
                const response = await fetch('/api/user/roles');
                if (response.ok) {
                    const data = await response.json();
                    setUserAccess(data.access);
                }
            } catch (error) {
                console.error('Failed to fetch user roles:', error);
                // Default to showing all menus if roles API fails
                setUserAccess({
                    dashboard: true,
                    profile: true,
                    purj: true,
                    finance: true,
                    asset: true,
                    elearning: true,
                    myprofile: true,
                    sdm_gereja: false,
                    anggota: true,
                    analitik: true,
                    forum: true,
                    messages: true,
                    kelola_klasis: false,
                    kelola_sinodewilayah: false,
                    kelola_sinode: false,
                    litbang_klasis: false,
                    litbang_sinodewilayah: false,
                    litbang_sinode: false,
                });
            }
        }
        if (isAuthenticated) {
            fetchUserRoles();
        }
    }, [isAuthenticated]);

    useEffect(() => {
        if (!isLoading && !isAuthenticated) {
            router.replace('/login');
        }
    }, [isAuthenticated, isLoading, router]);

    // Check onboarding status based on minimum profile completeness
    useEffect(() => {
        async function checkOnboarding() {
            if (pathname === '/onboarding') {
                setOnboardingComplete(false);
                return;
            }
            // If user already skipped onboarding in this session, don't redirect
            if (typeof window !== 'undefined' && sessionStorage.getItem('onboarding_skipped')) {
                setOnboardingComplete(true);
                return;
            }
            try {
                const res = await fetch('/api/user/onboarding');
                const data = await res.json();
                if (data.success) {
                    // If no employee data, skip onboarding (user is not linked to employee)
                    if (!data.data) {
                        setOnboardingComplete(true);
                        return;
                    }
                    if (data.onboarding) {
                        const complete = data.onboarding.is_onboarding_complete;
                        setOnboardingComplete(complete);
                        if (!complete) {
                            router.replace('/onboarding');
                        }
                    } else {
                        setOnboardingComplete(true);
                    }
                } else {
                    setOnboardingComplete(true);
                }
            } catch {
                setOnboardingComplete(true);
            }
        }
        if (isAuthenticated) {
            checkOnboarding();
        }
    }, [isAuthenticated, pathname, router]);

    const handleLogout = async () => {
        await logout();
        router.replace('/login');
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gki-gray-50 dark:bg-gki-gray-900">
                <div className="w-16 h-16 border-4 border-gki-blue/30 border-t-gki-blue rounded-full animate-spin" />
            </div>
        );
    }

    if (!isAuthenticated) {
        return null;
    }

    // Onboarding page gets a clean layout (no sidebar)
    if (pathname === '/onboarding') {
        return <>{children}</>;
    }

    return (
        <div className="min-h-screen bg-gki-gray-50 dark:bg-gki-gray-900">
            {/* Mobile menu overlay */}
            {mobileMenuOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-40 lg:hidden"
                    onClick={() => setMobileMenuOpen(false)}
                />
            )}

            {/* Sidebar */}
            <aside
                className={`
          fixed top-0 left-0 h-full bg-white dark:bg-gki-gray-800 shadow-xl z-50
          transition-all duration-300 ease-in-out
          ${sidebarOpen ? 'w-64' : 'w-20'}
          ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
            >
                {/* Flex container for sidebar content */}
                <div className="flex flex-col h-full">
                    {/* Logo */}
                    <div className="h-16 flex items-center justify-between px-4 border-b border-gki-gray-100 dark:border-gki-gray-700">
                        <div className="flex items-center gap-3">
                            <div className="relative h-10 w-auto flex items-center justify-center">
                                {/* Logo - light mode (black) and dark mode (white) */}
                                <img src="/logo-gki-b.png" alt="GKI One Logo" className="h-10 w-auto object-contain dark:hidden" />
                                <img src="/logo-gki-w.png" alt="GKI One Logo" className="h-10 w-auto object-contain hidden dark:block" />
                            </div>
                            {sidebarOpen && (
                                <span className="font-bold text-gki-blue text-lg hidden">GKI.ONE</span>
                                // Hidden text if logo contains text, or keep it if logo is just symbol. 
                                // Assuming logo-gki-b.png has text based on filename 'b' (black text?)
                                // Let's assume for now we keep text or remove it based on visual. 
                                // Safe bet: Show image, maybe hide text if image is wide.
                                // Let's just use image for now as requested "logo as branding".
                            )}
                        </div>
                        <button
                            onClick={() => setSidebarOpen(!sidebarOpen)}
                            className="hidden lg:block p-1.5 rounded-lg text-gki-gray-400 hover:bg-gki-gray-100 dark:hover:bg-gki-gray-700 transition-colors"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                {sidebarOpen ? (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
                                ) : (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
                                )}
                            </svg>
                        </button>
                    </div>

                    {/* Navigation - scrollable */}
                    <nav className="flex-1 overflow-y-auto p-4 space-y-2">
                        {/* Skeleton placeholders while roles are loading */}
                        {!userAccess && [1, 2, 3].map((i) => (
                            <div key={i} className="flex items-center gap-3 px-3 py-2.5">
                                <div className="w-5 h-5 rounded bg-gki-gray-200 dark:bg-gki-gray-700 animate-pulse" />
                                {sidebarOpen && (
                                    <div className="h-4 rounded bg-gki-gray-200 dark:bg-gki-gray-700 animate-pulse"
                                        style={{ width: `${60 + i * 20}px` }} />
                                )}
                            </div>
                        ))}
                        {/* Actual navigation - only shown after roles are loaded */}
                        {userAccess && navigation
                            .filter((item) => {
                                // 'always' items are always shown
                                if (item.access === 'always') return true;
                                // Filter based on access property
                                return userAccess[item.access as keyof UserAccess];
                            })
                            .map((item) => {
                                const isActive = pathname === item.href;
                                const hasChildren = item.children && item.children.length > 0;
                                const isChildActive = item.children?.some(child => pathname === child.href);
                                const isExpanded = expandedMenus.includes(item.name);

                                // If has children, render as expandable menu group
                                if (hasChildren) {
                                    return (
                                        <div key={item.name} className="space-y-1">
                                            {/* Menu Group Header - NOT a link */}
                                            <button
                                                onClick={() => {
                                                    // If sidebar is collapsed, expand it first
                                                    if (!sidebarOpen) {
                                                        setSidebarOpen(true);
                                                        // Also expand this menu group
                                                        if (!expandedMenus.includes(item.name)) {
                                                            setExpandedMenus(prev => [...prev, item.name]);
                                                        }
                                                    } else {
                                                        toggleMenu(item.name);
                                                    }
                                                }}
                                                className={`
                                                w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200
                                                ${isChildActive
                                                        ? 'bg-gki-blue/10 text-gki-blue dark:text-gki-blue-light border-l-3 border-gki-blue'
                                                        : 'text-gki-gray-500 dark:text-gki-gray-400 hover:bg-gki-gray-100 dark:hover:bg-gki-gray-700/50'
                                                    }
