                                                        </div>
                                                        {!n.is_read && <div className="w-2 h-2 bg-gki-blue rounded-full flex-shrink-0 mt-1.5" />}
                                                    </a>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                </>
                            )}
                        </div>

                        {/* Dynamic Context Selector - shows appropriate selector based on URL */}
                        <DynamicContextSelector pathname={pathname} />
                    </div>
                </header>

                {/* Page content */}
                <main className="p-4 lg:p-6">
                    {children}
                </main>

                {/* Floating scroll buttons */}
                <ScrollButtons />
            </div>
        </div>
    );
}

// Jemaat Selector Component
function JemaatSelector() {
    const { jemaatList, fullJemaatList, selectedJemaatId, setSelectedJemaatId, isLoading } = useJemaat();

    if (isLoading) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-gki-gray-100 dark:bg-gki-gray-700 rounded-lg">
                <div className="w-4 h-4 border-2 border-gki-gray-300 border-t-gki-blue rounded-full animate-spin" />
                <span className="text-xs text-gki-gray-400">Loading...</span>
            </div>
        );
    }

    if (jemaatList.length === 0) {
        return null;
    }

    if (jemaatList.length === 1) {
        return (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-gki-gray-100 dark:bg-gki-gray-700 rounded-lg">
                <svg className="w-4 h-4 text-gki-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
                <span className="text-sm font-medium text-gki-gray-700 dark:text-gray-200">
                    {jemaatList[0].name}
                </span>
            </div>
        );
    }

    // Group jemaat by klasis
    const grouped = fullJemaatList.reduce<Record<string, { klasisName: string; jemaats: { id: number; name: string }[] }>>((acc, j) => {
        const klasisKey = j.klasis_id ? String(j.klasis_id[0]) : '_none';
        const klasisName = j.klasis_id ? j.klasis_id[1] : 'Lainnya';
        if (!acc[klasisKey]) {
            acc[klasisKey] = { klasisName, jemaats: [] };
        }
        acc[klasisKey].jemaats.push({ id: j.id, name: j.name });
        return acc;
    }, {});

    // Sort klasis groups alphabetically, put "Lainnya" last
    const sortedGroups = Object.entries(grouped).sort(([keyA, a], [keyB, b]) => {
        if (keyA === '_none') return 1;
        if (keyB === '_none') return -1;
        return a.klasisName.localeCompare(b.klasisName);
    });

    // Sort jemaats within each group alphabetically
    sortedGroups.forEach(([, group]) => {
        group.jemaats.sort((a, b) => a.name.localeCompare(b.name));
    });

    const hasMultipleGroups = sortedGroups.length > 1;

    return (
        <div className="flex items-center gap-2">
            <svg className="w-4 h-4 text-gki-gray-500 dark:text-gki-gray-400 hidden sm:block" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
            <select
                value={selectedJemaatId || ''}
                onChange={(e) => setSelectedJemaatId(Number(e.target.value))}
                className="block min-w-[180px] max-w-[280px] rounded-lg border border-gki-gray-200 dark:border-gki-gray-600 bg-white dark:bg-gki-gray-700 py-1.5 pl-3 pr-8 text-sm font-medium text-gki-gray-900 dark:text-white shadow-sm focus:border-gki-blue focus:ring-2 focus:ring-gki-blue/20 focus:outline-none cursor-pointer hover:border-gki-blue/50 transition-colors appearance-none bg-no-repeat bg-right"
                style={{
                    backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`,
                    backgroundPosition: 'right 0.5rem center',
                    backgroundSize: '1.5em 1.5em'
                }}
            >
                {hasMultipleGroups ? (
                    sortedGroups.map(([key, group]) => (
                        <optgroup key={key} label={group.klasisName}>
                            {group.jemaats.map((j) => (
                                <option key={j.id} value={j.id}>
                                    {j.name}
                                </option>
                            ))}
                        </optgroup>
                    ))
                ) : (
                    jemaatList.map((j) => (
                        <option key={j.id} value={j.id}>
                            {j.name}
                        </option>
                    ))
                )}
            </select>
        </div>
    );
}

// Dynamic Context Selector - shows appropriate selector based on URL path
function DynamicContextSelector({ pathname }: { pathname: string }) {
    // Determine which selector to show based on URL path
    if (pathname.startsWith('/klasis')) {
        return <KlasisSelector />;
    }
    if (pathname.startsWith('/sinodewilayah')) {
        return <SinodeWilayahSelector />;
    }
    if (pathname.startsWith('/sinode')) {
        return <SinodeSelector />;
    }
    // SDM pages don't need jemaat filter - they show all data
    if (pathname.startsWith('/sdm')) {
        return null;
    }
    // Default: show Jemaat selector
    return <JemaatSelector />;
}

